let md = $json.cleanedMarkdown;

// Remove separators
md = md.replace(/^[-_]{3,}$/gm, '');

// Convert headers with tight spacing
md = md
  .replace(/^### (.*$)/gim, '<h3>$1</h3><br/>')
  .replace(/^## (.*$)/gim, '<h2>$1</h2><br/>')
  .replace(/^# (.*$)/gim, '<h1>$1</h1><br/>');

// Convert bold/italic
md = md
  .replace(/\*\*(.*?)\*\*/gim, '<strong>$1</strong>')
  .replace(/\*(.*?)\*/gim, '<em>$1</em>');

// Convert tables (basic)
md = md.replace(
  /\|(.+)\|\n\|[-\s|]+\|\n((\|.*\|\n?)*)/g,
  (match) => {
    const rows = match.trim().split('\n');
    const headers = rows[0].split('|').filter(Boolean);
    const bodyRows = rows.slice(2);

    let table = '<table><tbody><tr>';
    headers.forEach(h => table += `<th>${h.trim()}</th>`);
    table += '</tr>';

    bodyRows.forEach(row => {
      const cols = row.split('|').filter(Boolean);
      table += '<tr>';
      cols.forEach(c => table += `<td>${c.trim()}</td>`);
      table += '</tr>';
    });

    table += '</tbody></table>';
    return table;
  }
);

// Line breaks
md = md.replace(/\n/g, '<br/>');
md = md.replace(/(<br\/>\s*){2,}/g, '<br/>');

return [{
  json: {
    ...$json,
    html: md
  }
}];

let raw = $json.rawMarkdown;

try {
  // ✅ Step 1: Clean invalid trailing delimiters or junk
  let cleaned = raw
    .replace(/--- USER_STORY_BREAK ---/g, '')   // remove delimiter
    .trim();

  // ✅ Step 2: Extract ONLY valid JSON (safe guard)
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');

  if (firstBrace !== -1 && lastBrace !== -1) {
    cleaned = cleaned.substring(firstBrace, lastBrace + 1);
  }

  // ✅ Step 3: Parse JSON
  const parsed = JSON.parse(cleaned);

  return [{
    json: {
      rawMarkdown: raw,
      cleanedJson: cleaned,
      structuredData: parsed,
      parsingError: false
    }
  }];

} catch (err) {

  return [{
    json: {
      rawMarkdown: raw,
      structuredData: null,
      parsingError: true,
      errorMessage: err.message
    }
  }];
}

const data = $json.structuredData ?? {};

const userStories = Array.isArray(data.userStories)
  ? data.userStories
  : [];

const filteredStories = userStories.filter(
  item => typeof item === 'object' && item !== null
);

return [
  {
    json: {
      structuredData: {
        ...data,
        userStories: filteredStories
      }
    }
  }
];

// Input 1: Original structured data
const structuredData = $items("Final Structured Data")[0].json.structuredData;
const inputEpics = structuredData.epics;
const userStories = structuredData.userStories;

// Build epicId → userStories map
const epicStoryMap = {};
userStories.forEach(story => {
  if (!epicStoryMap[story.epicId]) {
    epicStoryMap[story.epicId] = [];
  }
  epicStoryMap[story.epicId].push(story);
});

// Input 2: JIRA search results
const jiraIssues = $input.all().flatMap(item => item.json.issues || []);

// Build map of existing epics (by summary)
const existingMap = {};
jiraIssues.forEach(issue => {
  const summary = issue.fields.summary;
  existingMap[summary] = {
    epicKey: issue.key,
    epicID: issue.id
  };
});

// Separate lists
const existingEpics = [];
const missingEpics = [];

inputEpics.forEach(epic => {
  const epicName = epic.epicName;

  const baseEpicData = {
    ...epic, // ✅ THIS preserves ALL epic fields
    userStories: epicStoryMap[epic.epicId] || []
  };

  if (existingMap[epicName]) {
    existingEpics.push({
      ...baseEpicData,
      epicKey: existingMap[epicName].epicKey,
      epicID: existingMap[epicName].epicID
    });
  } else {
    missingEpics.push(baseEpicData);
  }
});

return [
  {
    json: {
      existingEpics,
      missingEpics
    }
  }
];

return $input.all().map(item => {
  const issue = item.json.issues?.[0];

  return {
    json: {
      id: issue?.id || null,
      key: issue?.key || null,
      self: issue?.self || null

    }
  };
});

function generateId(epicName, story) {
  const str = epicName + JSON.stringify(story.userStory);

  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash |= 0; // Convert to 32bit int
  }

  return "ID_" + Math.abs(hash);
}

const output = [];

const existingEpics = $json.existingEpics || [];
const missingEpics = $json.missingEpics || [];

// Helper to extract epic-level fields (excluding userStories)
function extractEpicMeta(epic) {
  const { userStories, ...epicMeta } = epic;
  return epicMeta;
}

// ✅ Existing Epics
existingEpics.forEach(epic => {
  const epicMeta = extractEpicMeta(epic);

  (epic.userStories || []).forEach(story => {
    output.push({
      json: {
        ...epicMeta,   // ✅ includes epicDescription, businessObjective, etc.
        idempotencyKey: generateId(epic.epicName, story),
        ...story,
        epicExists: true
      }
    });
  });
});

// ✅ Missing Epics
missingEpics.forEach(epic => {
  const epicMeta = extractEpicMeta(epic);

  (epic.userStories || []).forEach(story => {
    output.push({
      json: {
        ...epicMeta,   // ✅ includes all epic-level fields
        idempotencyKey: generateId(epic.epicName, story),
        ...story,
        epicExists: false
      }
    });
  });
});

return output;

