const pages = $json.results || [];

return [{
  json: {
    ...$json,
    pageId: pages.length > 0 ? pages[0].id : null,
    pageExists: pages.length > 0,
    totalFound: pages.length
  }
}];

const items = $input.all();

const uniqueEpicsMap = {};

items.forEach(item => {
  const epic = item.json;

  // Only process if epic does NOT exist in JIRA
  if (!epic.epicExists) {
    const key = epic.epicName;

    if (!uniqueEpicsMap[key]) {
      uniqueEpicsMap[key] = {
        json: {
          epicName: epic.epicName,
          epicDescription: epic.epicDescription,
          businessObjective: epic.businessObjective,
          successMetrics: epic.successMetrics,
          sourceTraceability: epic.sourceTraceability,
          epicId: epic.epicId
        }
      };
    }
  }
});

return Object.values(uniqueEpicsMap);
